import React from "react";
import ReactDOM from "react-dom/client";
import { BrowserRouter, Routes, Route } from "react-router-dom";
import Bienvenida from "./components/Bienvenida";
import Ubicaciones from "./components/ubicac/Ubicaciones";
import Procesos from "./components/procesos/Procesos";
import AdminB from "./components/admin/AdminB";
import AdminS from "./components/admin/AdminS";
import AdminU from "./components/admin/AdminU";
import AdminP from "./components/admin/AdminP";
import "bootstrap/dist/css/bootstrap.min.css";
import "bootstrap-icons/font/bootstrap-icons.css";

const root = ReactDOM.createRoot(document.getElementById("root"));
root.render(
  <React.StrictMode>
    <BrowserRouter>
      <Routes>
        <Route path="/" element={<Bienvenida />} />
        <Route path="/procesos" element={<Procesos />} />
        <Route path="/ubicaciones" element={<Ubicaciones />} />
        <Route path="/adminB" element={<AdminB />} />
        <Route path="/admin/adminS" element={<AdminS />} />
        <Route path="/admin/adminU" element={<AdminU/>} />
        <Route path="/admin/adminP" element={<AdminP />} />
      </Routes>
    </BrowserRouter>
  </React.StrictMode>
);
